const logs=[["28 out 2026", "Problema resolvido", "Nem toda queda no placar é uma regressão.", "eval-regression-agent-not-retrieval", "Separar os resultados antes de reverter a release. As quedas estavam na execução ponta a ponta do agente; busca, carga e checks não mudaram.", "Um rejulgamento às cegas descartou desvio do juiz. As nove regressões aparentes foram atribuídas ao ruído da rodada do agente.", "evals · retrieval · análise de regressão"], ["28 out 2026", "Problema resolvido", "Um prompt melhor precisa de evidência.", "prompt-eval-isolated-subagents-blind-judges", "Avaliar 96 respostas isoladas, com juízes independentes e às cegas, em vez de escolher pela impressão.", "No teste reportado, respostas sem afirmações inventadas subiram de 75% para 92% no Sonnet; não houve ganho confiável no Haiku.", "prompt eval · experimentos · llm-as-judge"], ["14 out 2026", "Decisão", "A medição não pode quebrar o que mede.", "instrument-must-not-break-caller-pointer-rule", "Preservar o registro e descartar apenas o link inseguro, porque o instrumento roda no caminho de quem o chama.", "Duas regras divergentes unificadas; 552 testes passando e nenhum novo erro de tipo.", "observabilidade · python · integridade de dados"], ["8 out 2026", "Decisão", "Limitar o lote por bytes, não por registros.", "batch-size-bytes-not-count-experiment", "Testar contra um banco real para descobrir o limite efetivo do payload, em vez de adivinhar uma contagem segura.", "Lotes fixos de 100+ falharam em cinco de cinco execuções; o lote limitado por bytes rodou sem erros 413.", "surrealdb · confiabilidade · experimento"], ["11 jul 2026", "Entregue", "Do trabalho real ao portfólio publicado.", "living-portfolio-engine", "Curar sessões por relevância, escrever em duas camadas e dois idiomas, sanitizar e enviar para revisão.", "O pipeline já produz o site original. Este protótipo é apenas uma proposta visual, sem ligação com a automação.", "astro · mcp · python · claude-code"], ["9 jul 2026", "Decisão", "Git como banco. Revisão como limite.", "git-as-database", "Guardar conteúdo em JSON no Git e usar uma branch de rascunhos como barreira antes da publicação.", "Histórico auditável e site estático, sem backend para operar. A automação escreve; o humano faz o merge.", "arquitetura · git · astro · static-site"]];const root=document.querySelector('#logs');root.innerHTML=logs.map((l,i)=>`<details class="log" data-type="${l[1]}"><summary><span class="date">${l[0]}<br>${l[1]}</span><h3>${l[2]}</h3></summary><div class="log-body"><p><b>Escolha e raciocínio</b><br>${l[4]}</p><p><b>Validação registrada</b><br>${l[5]}</p><div class="tags">${l[6]}</div><a href="https://portifolio-vivo.pages.dev/pt/#feed-2026-${i<2?'10-28':i===2?'10-14':i===3?'10-08':i===4?'07-11':'07-09'}-${l[3]}" target="_blank" rel="noopener">Ler registro original →</a></div></details>`).join('');const search=document.querySelector('#search'),type=document.querySelector('#type');function filter(){const q=search.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();let n=0;document.querySelectorAll('.log').forEach(x=>{const text=x.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();x.hidden=!(text.includes(q)&&(type.value==='all'||x.dataset.type===type.value));if(!x.hidden)n++});document.querySelector('#count').textContent=n+' de '+logs.length+' registros selecionados';document.querySelector('#empty').hidden=n>0}search.addEventListener('input',filter);type.addEventListener('change',filter);filter();